// ESP32 — RGB-LED Farbwechsel

#define PIN_R 25
#define PIN_G 26
#define PIN_B 27

#define CH_R 0
#define CH_G 1
#define CH_B 2

#define PWM_FREQ 5000
#define PWM_RES  8

void setColor(uint8_t r, uint8_t g, uint8_t b) {
  ledcWrite(CH_R, r);
  ledcWrite(CH_G, g);
  ledcWrite(CH_B, b);
}

void setup() {
  ledcSetup(CH_R, PWM_FREQ, PWM_RES);
  ledcSetup(CH_G, PWM_FREQ, PWM_RES);
  ledcSetup(CH_B, PWM_FREQ, PWM_RES);

  ledcAttachPin(PIN_R, CH_R);
  ledcAttachPin(PIN_G, CH_G);
  ledcAttachPin(PIN_B, CH_B);
}

void loop() {
  // Orange: Rot voll, Grün halb, kein Blau
  setColor(255, 128, 0);
  delay(1000);

  // Türkis: kein Rot, Grün voll, Blau voll
  setColor(0, 255, 200);
  delay(1000);

  // Magenta: Rot voll, kein Grün, Blau voll
  setColor(255, 0, 255);
  delay(1000);
}
